<?php requirePermission('purchases');
if($_SERVER['REQUEST_METHOD']==='POST'){checkCsrf();try{$pdo->beginTransaction();$supplier=(int)($_POST['supplier_id']??0);$product=(int)($_POST['product_id']??0);$qty=max(1,(int)($_POST['quantity']??1));$cost=max(0,(float)($_POST['unit_cost']??0));$due=$_POST['due_date']?:null;$invoice=trim($_POST['invoice_number']??'');if(!$supplier||!$product)throw new Exception('Informe fornecedor e produto.');$total=$qty*$cost;$pdo->prepare('INSERT INTO purchases(supplier_id,user_id,invoice_number,total,status,created_at) VALUES(?,?,?,?,"received",NOW())')->execute([$supplier,$_SESSION['user']['id'],$invoice,$total]);$pid=$pdo->lastInsertId();$pdo->prepare('INSERT INTO purchase_items(purchase_id,product_id,quantity,unit_cost,total) VALUES(?,?,?,?,?)')->execute([$pid,$product,$qty,$cost,$total]);$pdo->prepare('UPDATE products SET stock=stock+?,cost=? WHERE id=?')->execute([$qty,$cost,$product]);$pdo->prepare('INSERT INTO stock_movements(product_id,user_id,type,quantity,reference,notes) VALUES(?,? ,"purchase",?,?,?)')->execute([$product,$_SESSION['user']['id'],$qty,'PUR-'.$pid,'Entrada por compra']);if($due){$pdo->prepare('INSERT INTO accounts_payable(supplier_id,purchase_id,description,amount,due_date,status) VALUES(?,?,?,?,?,"open")')->execute([$supplier,$pid,'Compra #'.$pid,$total,$due]);}$pdo->commit();flash('success','Compra #'.$pid.' recebida e estoque atualizado.');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash('error',$e->getMessage());}redirect('index.php?page=purchases');}
$suppliers=$pdo->query('SELECT id,name FROM suppliers ORDER BY name')->fetchAll();$products=$pdo->query('SELECT id,name,sku,cost,stock FROM products WHERE active=1 ORDER BY name')->fetchAll();$rows=$pdo->query('SELECT p.*,s.name supplier,u.name buyer FROM purchases p JOIN suppliers s ON s.id=p.supplier_id JOIN users u ON u.id=p.user_id ORDER BY p.id DESC LIMIT 50')->fetchAll();$title='Compras';require __DIR__.'/../../includes/header.php';?>
<div class="page-head"><div><h1>Compras e entrada de estoque</h1><p>Recebimento de mercadorias com custo, fornecedor e contas a pagar.</p></div></div><div class="grid two"><section class="panel"><h2>Registrar compra</h2><form method="post" class="stack"><input type="hidden" name="csrf" value="<?=csrf()?>"><label>Fornecedor<select name="supplier_id" required><option value="">Selecione...</option><?php foreach($suppliers as $s):?><option value="<?=$s['id']?>"><?=e($s['name'])?></option><?php endforeach;?></select></label><label>Produto<select name="product_id" required><option value="">Selecione...</option><?php foreach($products as $p):?><option value="<?=$p['id']?>"><?=e($p['name'])?> · <?=e($p['sku'])?> · estoque <?=$p['stock']?></option><?php endforeach;?></select></label><div class="form-grid"><label>Quantidade<input name="quantity" type="number" min="1" value="1" required></label><label>Custo unitário<input name="unit_cost" type="number" step="0.01" min="0" required></label><label>Nº Nota/Pedido<input name="invoice_number"></label><label>Vencimento a pagar<input name="due_date" type="date"></label></div><button class="btn primary">Receber compra</button></form></section><section class="panel"><h2>Últimas compras</h2><div class="table-wrap"><table><thead><tr><th>#</th><th>Fornecedor</th><th>Documento</th><th>Total</th><th>Data</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td>#<?=$r['id']?></td><td><?=e($r['supplier'])?></td><td><?=e($r['invoice_number'])?></td><td><?=money($r['total'])?></td><td><?=date('d/m/Y H:i',strtotime($r['created_at']))?></td></tr><?php endforeach;?></tbody></table></div></section></div><?php require __DIR__.'/../../includes/footer.php';?>
